insert into public.lectures
  (slug, title, card_title, list_title, hero_title, hero_subtitle, speaker_name,
   card_image, hero_image, blocks, status, registration_open, sort_order)
values ('paul-baker-14', 'CISMA Lecture Series 14: Paul Baker', 'CISMA Lecture Series 14: Paul Baker', 'CISMA Lecture Series 14: Paul Baker',
  'CISMA Lecture Series 14', 'Paul Baker', 'Paul Baker',
  '/events/paul-baker-14.jpeg', '/events/paul-baker-hero.png',
  '[{"type":"heading","text":"Surprise Words and Core Words: Using Vibe Coding to Identify Collocational Divergence Across Corpora"},{"type":"heading","text":"About the lecture"},{"type":"text","align":"justify","text":"This lecture explores an innovative approach to corpus linguistics by introducing the concepts of surprise words (s-words) and core words (c-words). It examines how words can behave differently across two corpora, even when conventional keyword analysis does not reveal these differences.\n\nThe talk introduces the S-Word Analysis Tool (SWAT), developed with the assistance of a large language model, to identify and rank words according to differences in their collocational patterns. By comparing the words that frequently occur alongside a particular word in different corpora, the tool helps researchers identify distinctive patterns of language use and investigate their meanings in context.\n\nUsing a case study comparing representations of obesity in The Guardian and The Sun, the lecture demonstrates how this approach can uncover differences in discourse framing, particularly in discussions of responsibility, cost, and possible solutions.\n\nThe session highlights the potential of vibe coding and large language models to support the development of new corpus-linguistic tools and analytical methods. It will be particularly relevant to researchers and students interested in corpus linguistics, discourse analysis, computational linguistics, and AI-assisted language research."},{"type":"heading","text":"About the speaker"},{"type":"image","src":"/events/paul-baker.jpg","has":true,"width":"sm","alt":"Professor Paul Baker"},{"type":"text","bold":true,"text":"Professor Paul Baker"},{"type":"text","text":"Department of English and Communication\nThe Hong Kong Polytechnic University"},{"type":"text","align":"justify","text":"Professor Paul Baker is a leading scholar in corpus linguistics and discourse analysis. He is Professor in the Department of English and Communication at The Hong Kong Polytechnic University. His research focuses on corpus-assisted discourse studies, language variation, and the use of corpus methods to investigate linguistic patterns across different texts and contexts.\n\nHis work demonstrates how corpus-based approaches can help researchers explore language use systematically, identify patterns of meaning, and investigate how language varies across genres and communicative settings. His expertise makes a valuable contribution to the fields of corpus linguistics, discourse studies, and language research."},{"type":"heading","text":"Hosts"},{"type":"text","text":"Founder and Co-Chair, CISMA\nAssociate Professor, Shanghai International Studies University"},{"type":"text","bold":true,"text":"Shanshan Xiao"},{"type":"text","text":"Coordinator, PhD Candidate\nShanghai International Studies University"},{"type":"heading","text":"Date and platform"},{"type":"text","text":"27 October 2026\n16:00 China Standard Time (13:00 Pakistan time, 08:00 UTC)\nOnline webinar"}]'::jsonb, 'past', false, 15)
