insert into public.lectures
  (slug, title, card_title, list_title, hero_title, hero_subtitle, speaker_name,
   card_image, hero_image, blocks, status, registration_open, sort_order)
values ('cisma-live-randi-reppen', 'CISMA Live | Corpus Linguistics Today: A Conversation with Randi Reppen', 'CISMA Live: Corpus Linguistics Today, A Conversation with Randi Reppen', 'CISMA Live | Corpus Linguistics Today: A Conversation with Randi Reppen',
  'CISMA Live', 'Corpus Linguistics Today: A Conversation with Randi Reppen', 'Randi Reppen and Muhammad Afzaal',
  '/cisma-live-poster.png', '/events/cisma-live-hero.jpeg',
  '[{"type":"heading","text":"About the conversation"},{"type":"text","align":"justify","text":"How can corpus evidence help us better understand language, strengthen linguistic research, and improve teaching practices? This special CISMA conversation brings together Professor Randi Reppen and Dr. Muhammad Afzaal to explore contemporary developments in corpus linguistics and its practical applications.\n\nDrawing on her extensive experience in corpus research and language education, Professor Reppen discusses the importance of authentic language data, effective research methodologies, and the relationship between linguistic analysis and real-world applications. The conversation also explores emerging trends in quantitative approaches, artificial intelligence, and corpus-informed language instruction.\n\nThe session highlights how corpus-based methods can help researchers identify patterns of language use, develop evidence-based insights, and bridge the gap between linguistic research and educational practice."},{"type":"heading","text":"Key topics"},{"type":"text","align":"left","text":"• Tools in corpus linguistics: advantages and challenges\n• The role of linguistics in corpus-based research\n• Corpus-informed language teaching and learning\n• Quantitative methods and emerging applications of AI\n• Research developments and future directions in corpus linguistics"},{"type":"heading","text":"About the speaker"},{"type":"image","src":"/events/randi-reppen.jpg","has":true,"width":"sm","alt":"Professor Randi Reppen"},{"type":"text","bold":true,"text":"Professor Randi Reppen"},{"type":"text","text":"Professor Emerita of Applied Linguistics and TESL\nNorthern Arizona University, USA"},{"type":"text","align":"justify","text":"Professor Randi Reppen is Professor Emerita of Applied Linguistics and Teaching English as a Second Language (TESL) at Northern Arizona University, USA. Her research focuses on corpus linguistics and its applications in language teaching, linguistic research, and educational materials development.\n\nShe has extensive experience in teaching English language learners, training language teachers, and directing research projects involving large collections of spoken and written language. Her professional work includes contributions to major corpus compilation projects and the development of corpus-informed language learning resources.\n\nThrough her research and academic contributions, Professor Reppen has helped demonstrate how corpus-based evidence can connect linguistic research with practical teaching and learning applications."},{"type":"heading","text":"Date and platform"},{"type":"text","text":"September 13\n11:00 PM Shanghai Time / 8:00 PM Pakistan Time\nOnline, via Zoom"}]'::jsonb, 'past', false, 14)
