insert into public.lectures
  (slug, title, card_title, list_title, hero_title, hero_subtitle, speaker_name,
   card_image, hero_image, blocks, status, registration_open, sort_order)
values ('retraction-to-research-integrity', 'From retraction to research integrity: What does it mean for grassroots researchers?', 'From retraction to research integrity: What does it mean for grassroots...', 'From retraction to research integrity: What does it mean for grassroots researchers?',
  'From retraction to research integrity: What does it mean for grassroots researchers?', 'Shaoxiong Brian Xu (徐少雄)', 'Shaoxiong Brian Xu (徐少雄)',
  '/lecture-1.webp', '/lecture-1.webp',
  '[{"type":"heading","text":"From retraction to research integrity: What does it mean for grassroots researchers?"},{"type":"text","text":"Amid the growing movement of post-publication peer review, retractions are increasingly serving as a vital mechanism for correcting the academic record. However, despite being a key indicator of research integrity issues, the mechanics and implications of retractions remain unfamiliar to many researchers, particularly those in the social sciences and humanities. In this talk, I will draw on the Retraction Watch Database to map the salient characteristics of global retractions, including their prevalence, underlying reasons, time lags, authorship patterns, and distribution across geographic locations and academic disciplines. Building on this empirical foundation, I will provide an overview of the current landscape of retraction research and identify critical directions for future inquiry. Crucially, this talk will translate these macro-level trends into practical insights. I will highlight the negative consequences of retractions, including potential sanctions for accountable parties, and conclude with actionable advice for grassroots researchers. Specifically, I will discuss how to appropriately handle research integrity allegations, respond to retraction requests, manage citations of retracted literature, and navigate collaborations with researchers who have (co-)authored retracted publications.","align":"justify"},{"type":"heading","text":"About the Speaker"},{"type":"image","src":"/speaker-shaoxiong-xu.webp","has":true,"width":"md","alt":"Shaoxiong Brian Xu (徐少雄)"},{"type":"text","text":"Shaoxiong Brian Xu (徐少雄) is a Postdoctoral Research Fellow in the Department of English and Communication at The Hong Kong Polytechnic University. Since 2017, his research has focused on the phenomenon of academic retractions. Specifically, he investigates retraction notices as a high-stakes academic genre, exploring how retraction stigma is communicated both linguistically and rhetorically. His broader work also examines potential predatory journals and the landscape of research integrity within China. His scholarly work has appeared in prominent peer-reviewed journals, such as Accountability in Research, Science and Engineering Ethics, Learned Publishing, Ethics & Behavior, and Minerva. Additionally, he has contributed editorial materials on retractions to prestigious outlets such as Nature and Nature Human Behaviour.","align":"justify"},{"type":"heading","text":"Attendance Info:"},{"type":"text","text":"Zoom Meeting ID: 838 6814 2735\nPasscode: 797375\nDate: June 27th, 6pm (Beijing Time)","align":"left"}]'::jsonb, 'past', false, 13)
