values ('ai-abstracts-vs-human-abstracts-session9', 'A Genre-Based Comparison of Chat-GPT-Generated Abstracts Versus Human-Authored Abstracts: Focus on Applied Linguistics Research Articles', 'CISMA Lecture Series: Session 9', 'CISMA Lecture Series: Session 9',
  'CISMA Lecture Series: Session 9', 'Can AI-written abstracts pass the academic “check-up”? Join us for this cutting-edge talk!', 'Dina Abdel Salam El-Dakhs',
  '/lecture-5.webp', '/lecture-5.webp',
  '[{"type":"text","text":"ChatGPT 生成的摘要 vs. 人类作者撰写的摘要： 基于应用语言学研究论文的体裁对比分析","bold":true},{"type":"text","text":"A Genre-Based Comparison of Chat-GPT-Generated Abstracts Versus Human-Authored Abstracts: Focus on Applied Linguistics Research Articles"},{"type":"image","src":"/session9-poster.webp","has":true,"width":"full","alt":"A Genre-Based Comparison of Chat-GPT-Generated Abstracts Versus Human-Authored Abstracts: Focus on Applied Linguistics Research Articles"},{"type":"text","text":"Dina Abdel Salam El-Dakhs 教授","align":"left"},{"type":"text","text":"沙特阿拉伯 苏丹王子大学","align":"left"},{"type":"text","text":"语言学与翻译系主任、语言与交际研究实验室负责人","align":"left"},{"type":"text","text":"Chair of Linguistics and Translation, Leader of Language and Communication Research Lab, Prince Sultan University, Saudi Arabia","align":"left"},{"type":"text","text":"🎓 研究专长 / Research Interests","align":"left"},{"type":"text","text":"心理语言学、语用学、话语分析、二语教学","align":"left"},{"type":"text","text":"Psycholinguistics, Pragmatics, Discourse Analysis, Second Language Learning and Teaching","align":"left"},{"type":"text","text":"📘 讲座简介 / Overview","align":"left"},{"type":"text","text":"随着 ChatGPT 等生成式 AI 工具在学术写作中的普及，一个关键问题浮出水面：","align":"left"},{"type":"text","text":"机器撰写的文本，能否契合学科规范与学术期待？","align":"left"},{"type":"text","text":"本讲座以应用语言学研究论文摘要为语料，基于语类结构与元话语模型，系统比较 AI 生成摘要与人类撰写摘要在结构组织、交际目的、作者-读者互动等方面的异同。","align":"left"},{"type":"text","text":"我们将揭示：为何摘要可以成为观察人机写作差异的切入点。","align":"left"},{"type":"text","text":"As generative AI tools like ChatGPT become common in academic writing, questions arise:","align":"left"},{"type":"text","text":"Can machine-generated texts meet disciplinary standards and scholarly expectations?","align":"left"},{"type":"text","text":"This talk offers a genre-based comparison of research article abstracts in Applied Linguistics.","align":"left"},{"type":"text","text":"Using models of rhetorical move structure and metadiscourse, it analyzes how AI-written abstracts differ from human-authored ones—in organization, purpose, and interaction with readers.","align":"left"},{"type":"text","text":"Abstracts, it turns out, are a powerful lens for examining human–AI writing differences.","align":"left"},{"type":"text","text":"👥 适合人群 / Audience","align":"left"},{"type":"text","text":"科研人员 / Researchers","align":"left"},{"type":"text","text":"学术写作教师 / Writing Instructors","align":"left"},{"type":"text","text":"研究生 / Graduate Students","align":"left"},{"type":"text","text":"所有关注AI与学术传播的人 / Anyone interested in AI and scholarly communication","align":"left"},{"type":"text","text":"🌐 主办 / Organizer","align":"left"},{"type":"text","text":"Muhammad Afzaal","align":"left"},{"type":"text","text":"上海外国语大学 语言科学研究院","align":"left"},{"type":"text","text":"ILS, Shanghai International Studies University, China","align":"left"},{"type":"text","text":"📅 时间 / Time","align":"left"},{"type":"text","text":"Feb 14th, 2026","align":"left"},{"type":"text","text":"12:00 PM Saudi Arabia","align":"left"},{"type":"text","text":"17:00 PM China","align":"left"},{"type":"text","text":"📘 线上会议 / Zoom Meeting","align":"left"},{"type":"text","text":"ID: 839 0642 3599","align":"left"},{"type":"text","text":"密码 / Passcode: 342413","align":"left"}]'::jsonb, 'past', false, 9)
