values ('chatgpt-linguistic-research-education-session8', 'Critical Perspectives on ChatGPT in Linguistic Research and Education', 'CISMA Lecture Series: Session 8', 'CISMA Lecture Series: Session 8',
  'CISMA Lecture Series: Session 8', 'Critical Perspectives on ChatGPT in Linguistic Research and Education', 'Amanda Clare MURPHY',
  '/lecture-6.webp', '/lecture-6.webp',
  '[{"type":"text","text":"Critical Perspectives on ChatGPT in Linguistic Research and Education","bold":true},{"type":"text","text":"Amanda Clare MURPHY"},{"type":"image","src":"/speaker-amanda-murphy.webp","has":true,"width":"sm","alt":"Amanda Clare MURPHY"},{"type":"heading","text":"Speaker''s Bio"},{"type":"text","text":"Amanda Clare MURPHY","bold":true},{"type":"text","text":"Università Cattolica del Sacro Cuore, Italy"},{"type":"text","align":"justify","text":"Amanda C. Murphy (PhD, Birmingham, UK) is professor of English language, linguistics and translation, Director of the Centre for Higher Education Internationalisation, and Vice-Director of a Master''s in International HR Management at Università Cattolica del Sacro Cuore, Italy. A corpus linguist by nature, her publications range from topics within language teaching, including the critical use of AI, pronunciation pitfalls in English, comparative phraseology in English and Italian, media language and text types, and different types of specialized text. Within the area of internationalisation, she has published on internationalisation of the university at home, virtual exchange, curriculum change, English-medium instruction and Teacher Professional Development."},{"type":"heading","text":"Overview"},{"type":"text","align":"justify","text":"In this talk, I examine student attitudes to AI tools such as ChatGPT when they are used for linguistic analysis. Within the framework of inductive learning, I report on an experiment (Forchini and Murphy 2025) that investigated both the accuracy of textual analyses of dialogues in English, and student reflections on the performance of ChatGPT. The value of guidance from lecturers in terms of critical thinking and structured training in the use of AI is emphasised, as well as informed and responsible student engagement."},{"type":"heading","text":"Organizer: Muhammad Afzaal"},{"type":"image","src":"/committee-afzaal.webp","has":true,"width":"md","alt":"Muhammad Afzaal"},{"type":"text","text":"Associate Professor\nInstitute of Language Sciences\nShanghai International Studies University"},{"type":"heading","text":"Attendance"},{"type":"text","text":"Date: February 6th, 2026"},{"type":"text","text":"Time: 17:00 p.m. (Shanghai Time), 10:00 a.m. (Milan Time)"},{"type":"text","text":"Zoom Meeting ID: 886 0050 8808"},{"type":"text","text":"Passcode: 185115"},{"type":"image","src":"/session8-poster.webp","has":true,"width":"full","alt":"CISMA Lecture Series Session 8 poster"}]'::jsonb, 'past', false, 8)
